/**
 * TANVIONROYALE brand mark (inline SVG).
 *
 * Original TANVIONROYALE logo: a circular crest — outer gold ring, inner
 * royal-blue ring and a dark navy disc carrying the interlocked gold "T" and
 * blue "R" monogram. The geometry here mirrors app/icon.svg,
 * public/logo-mark.svg and the raster icons generated by
 * scripts/generate-brand-icons.mjs so the brand is pixel-consistent across
 * header, footer, hero, favicon and OG artwork.
 *
 * Rendered inline (no network request) and aria-hidden by default because it
 * is always paired with the visible "TANVIONROYALE" wordmark text; standalone
 * logo images elsewhere use alt="TANVIONROYALE logo".
 */
export function LogoMark({
  className = 'h-8 w-8',
  gradientId = 'tr-mark',
}: {
  className?: string;
  /** Unique per-instance id suffix — prevents duplicate SVG ids in the DOM. */
  gradientId?: string;
}) {
  const goldId = `tr-gold-${gradientId}`;
  const blueId = `tr-blue-${gradientId}`;
  const navyId = `tr-navy-${gradientId}`;
  return (
    <svg viewBox="0 0 100 100" className={className} aria-hidden="true" focusable="false">
      <defs>
        <linearGradient id={goldId} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stopColor="#ffd85e" />
          <stop offset="100%" stopColor="#b28418" />
        </linearGradient>
        <linearGradient id={blueId} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stopColor="#38bdf8" />
          <stop offset="100%" stopColor="#1d4ed8" />
        </linearGradient>
        <linearGradient id={navyId} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stopColor="#12264e" />
          <stop offset="100%" stopColor="#060e20" />
        </linearGradient>
      </defs>
      {/* Circular crest: outer gold ring, inner royal-blue ring, navy disc. */}
      <circle cx="50" cy="50" r="50" fill={`url(#${goldId})`} />
      <circle cx="50" cy="50" r="45.5" fill={`url(#${blueId})`} />
      <circle cx="50" cy="50" r="41.5" fill={`url(#${navyId})`} />
      {/* Gold "T" monogram */}
      <path fill={`url(#${goldId})`} d="M24 28h42v10H53v34H42V38H24z" />
      {/* Blue "R" monogram (drawn over the T, interlocked) */}
      <g fill={`url(#${blueId})`}>
        <rect x="57" y="38" width="9" height="34" />
        <path d="M56 47a10 10 0 0 1 20 0h-5.5a4.5 4.5 0 0 0-9 0z" />
        <path d="M63 50h11l5 22h-11z" />
      </g>
    </svg>
  );
}
